long long solve(const long long *values, int n) {
  if (n <= 0) return 0;
  long long *tails = (long long *)malloc(sizeof(long long) * (size_t)n);
  int size = 0;
  for (int i = 0; i < n; i++) {
    int low = 0, high = size;
    while (low < high) {
      int mid = low + (high - low) / 2;
      if (tails[mid] < values[i]) low = mid + 1;
      else high = mid;
    }
    tails[low] = values[i];
    if (low == size) size++;
  }
  free(tails);
  return (long long)size;
}

