long long solve(const vector<long long>& values) {
  vector<long long> tails;
  for (long long height : values) {
    auto slot = lower_bound(tails.begin(), tails.end(), height);
    if (slot == tails.end()) tails.push_back(height);
    else *slot = height;
  }
  return (long long)tails.size();
}

