def solve(values: list[int]) -> int:
    from bisect import bisect_left

    tails: list[int] = []
    for height in values:
        slot = bisect_left(tails, height)
        if slot == len(tails):
            tails.append(height)
        else:
            tails[slot] = height
    return len(tails)

