function solve(values) {
  const tails = [];
  for (const height of values) {
    let low = 0;
    let high = tails.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (tails[mid] < height) low = mid + 1;
      else high = mid;
    }
    if (low === tails.length) tails.push(height);
    else tails[low] = height;
  }
